ValidationRule.errorConditionFormula:
AND(
/* 1. Only apply when Country is United Kingdom or Ireland */
OR(
ISPICKVAL(Country__c, "United Kingdom"),
ISPICKVAL(Country__c, "Ireland")
),

/* 2. Only apply when Status Reason is Postpone Action */
ISPICKVAL(Status_Reason__c, "Postponed Action"),

/* 3. Reopen Date must be present and in the future */
OR(
ISBLANK(Case_Reopen_Date__c),
Case_Reopen_Date__c <= TODAY()
)
)
